def explicit(language):
    base = language if language.startswith('zh_') or language == 'ja_Hira' else language.split('_')[0]
    if language == 'ja_Kana':
        base = 'ja_Hira'
    names, paths = {}, {}
    for keys, rows, output in ((FUNCTION_KEYS, FUNCTION_ROWS, names),
                               (LOCAL_KEYS, LOCAL_ROWS, names), (PATH_KEYS, PATH_ROWS, paths)):
        if base in rows:
            values = rows[base].split('|')
            if len(values) != len(keys):
                raise ValueError('Wrong library terminology row width: ' + base)
            output.update(zip(keys, values))
    if language == 'ja_Kana':
        def convert(value):
            return ''.join(chr(ord(ch) + 0x60) if '\u3041' <= ch <= '\u3096' else ch for ch in value)
        names = {k: convert(v) for k, v in names.items()}
        paths = {k: convert(v) for k, v in paths.items()}
    # Avoid borrowed sound forms in the ordinary Japanese and Korean proposals.
    if base == 'ja':
        names = {k: v.replace('バイト', '八桁組') for k, v in names.items()}
    if base == 'ko':
        names = {k: v.replace('바이트', '여덟자리묶음') for k, v in names.items()}
    return names, paths
